questionvariables.text:
/* All measurements are multiples of 10cm within given ranges */

smallBoxArea:rand_with_step(80,120,10);
smallBoxHeight:rand_with_step(100,150,10);
largeBoxLength:rand_with_step(200,250,10);
largeBoxWidth:rand_with_step(100,200,10);
largeBoxHeight:rand_with_step(50,150,10);

smallBoxAreaExp:rand_with_prohib(0,2,[1]);
smallBoxHeightExp:rand_with_prohib(-1,2,[1, smallBoxAreaExp]);
largeBoxLengthExp:rand_with_prohib(-1,2,[1]);
largeBoxWidthExp:rand_with_prohib(-1,2,[1,largeBoxLengthExp]);
largeBoxHeightExp:rand_with_prohib(-1,2,[1,largeBoxWidthExp]);

smallBoxAreaUnit: if smallBoxAreaExp=0 then "{cm}^2" else "m^2";
smallBoxHeightUnit: if smallBoxHeightExp=-1 then "mm" else if smallBoxHeightExp=0 then "cm" else "m";
largeBoxLengthUnit: if largeBoxLengthExp=-1 then "mm" else if largeBoxLengthExp=0 then "cm" else "m";
largeBoxWidthUnit: if largeBoxWidthExp=-1 then "mm" else if largeBoxWidthExp=0 then "cm" else "m";
largeBoxHeightUnit: if largeBoxHeightExp=-1 then "mm" else if largeBoxHeightExp=0 then "cm" else "m";

smallBoxAreaDisp:smallBoxArea/(10^smallBoxAreaExp)^2;
smallBoxHeightDisp:smallBoxHeight/(10^smallBoxHeightExp);
largeBoxLengthDisp:largeBoxLength/(10^largeBoxLengthExp);
largeBoxWidthDisp:largeBoxWidth/(10^largeBoxWidthExp);
largeBoxHeightDisp:largeBoxHeight/(10^largeBoxHeightExp);

/* Unit and solution to (a) */
aUnitsExp:rand_with_prohib(0,2,[1]);
aUnits: if aUnitsExp=0 then "{cm}^3" else "m^3";
aSol:smallBoxArea*smallBoxHeight/(10^aUnitsExp)^3;

/* Unit and solution to (b) */
bUnitsExp:rand_with_prohib(0,2,[1,aUnitsExp]);
bUnits: if bUnitsExp=0 then "{cm}^3" else "m^3";
bSol:(smallBoxArea*smallBoxHeight+largeBoxLength*largeBoxWidth*largeBoxHeight)/(10^bUnitsExp)^3;

/* Unit and solution to (c) */
cUnitsExp:rand_with_prohib(0,2,[1]);
cUnits: if cUnitsExp=0 then "{cm}^2" else "m^2";
cSol:2*(largeBoxLength*largeBoxWidth+largeBoxWidth*largeBoxHeight+largeBoxHeight*largeBoxLength)/(10^cUnitsExp)^2;

feedbackvariables.text:
/* Node 1: Check correct answer */
/* Node 2: Worked solution */
/* Node 3: Check whether answer given in incorrect unit (out of m^3 and cm^3) */
node3_error: if aUnits="m^3" then aSol*1000000 else aSol/1000000;

/* Node 4: Check whether area conversion used square root of correct multiplier */
node4_error: if aUnits="m^3" then aSol*100 else aSol/100;

/* Node 5: Check whether answer out by a power of 10, suggests incorrect unit conversion */
node5_test: if float(floor(decimalplaces(log(ans1/aSol)/log(10),8)))=decimalplaces(log(ans1/aSol)/log(10),8) then 1 else 0;

/* Node 1: Check correct answer */
/* Node 2: Worked solution */

/* Node 3: Check ecf from volume in (a) (2) */
node3_test: if notequal(ans1,aSol) and ((bUnits="{cm}^3" and float(ans2)=float(ans1*1000000+largeBoxLength*largeBoxWidth*largeBoxHeight)) or (bUnits="m^3" and float(ans2)=float((ans1+largeBoxLength*largeBoxWidth*largeBoxHeight)/1000000))) then 1 else 0;

/* Node 4: Check whether answer given in wrong unit (out of m^3 and cm^3) (1) */
node4_error: if bUnits="m^3" then bSol*1000000 else bSol/1000000;

/* Node 5: Check whether implied volume of large box is correct but small box is out by a power of 10 */
node5_test: if (bUnits="m^3" and float(floor(decimalplaces(log((1000000*ans2-largeBoxLength*largeBoxWidth*largeBoxHeight)/ans1)/log(10),8)))=decimalplaces(log((1000000*ans2-largeBoxLength*largeBoxWidth*largeBoxHeight)/ans1)/log(10),8)) or (bUnits="{cm}^3" and float(floor(decimalplaces(log((ans2-largeBoxLength*largeBoxWidth*largeBoxHeight)/ans1)/log(10),8)))=decimalplaces(log((ans2-largeBoxLength*largeBoxWidth*largeBoxHeight)/ans1)/log(10),8)) then 1 else 0;

/* Node 6: Check whether implied volume of small box is correct but large box is out by a power of 10 */
node6_test: if (aUnits="m^3" and float(floor(decimalplaces(log((ans2-1000000*ans1)/(bSol-1000000*aSol))/log(10),8)))=decimalplaces(log((ans2-1000000*ans1)/(bSol-1000000*aSol))/log(10),8)) or (bUnits="m^3" and float(floor(decimalplaces(log((1000000*ans2-ans1)/(1000000*bSol-aSol))/log(10),8)))=decimalplaces(log((1000000*ans2-ans1)/(1000000*bSol-aSol))/log(10),8)) then 1 else 0;

/* Node 1: Check correct solution */
/* Node 2: Worked solution */
/* Node 3: Check whether answer given in wrong unit (out of m^3 and cm^3) (1) */
node3_error: if cUnits="m^2" then cSol*10000 else cSol/10000;
